        }

        .cc98-dashboard-list li {
          padding: 0.8rem 1.5rem;
          border-bottom: 1px dashed var(--border-color);
          cursor: pointer;
          transition: var(--cc98-transition);
        }

        .cc98-dashboard-list li:hover {
          background-color: var(--quote-bg);
        }

        .item-title {
          font-weight: 500;
          font-size: 0.92rem;
          color: var(--text-main);
          white-space: nowrap;
          overflow: hidden;
          text-overflow: ellipsis;
        }

        .item-title.comment-text {
          font-weight: normal;
          color: var(--text-main);
        }

        .item-meta {
          font-size: 0.78rem;
          color: var(--text-muted);
          display: flex;
          gap: 0.4rem;
          margin-top: 0.25rem;
          white-space: nowrap;
          overflow: hidden;
          text-overflow: ellipsis;
        }

        .source-topic {
          font-weight: bold;
        }

        .cc98-panel-btn {
          width: calc(100% - 3rem);
          margin: 1rem 1.5rem;
          padding: 0.5rem;
          background-color: transparent;
          border: 1px solid var(--border-color);
          color: var(--text-muted);
          border-radius: 4px;
          font-size: 0.85rem;
          font-weight: bold;
          cursor: pointer;
          transition: var(--cc98-transition);
        }

        .cc98-panel-btn:hover {
          color: var(--primary-color);
          border-color: var(--primary-color);
          background-color: var(--quote-bg);
        }

        /* Notif list specifics */
        .notif-list li {
          border-bottom: 1px solid var(--border-color);
        }

        .unread-item {
          background-color: rgba(251, 97, 101, 0.04);
        }

        .notif-header {
          display: flex;
          justify-content: space-between;
          font-size: 0.75rem;
          color: var(--text-muted);
          margin-bottom: 0.2rem;
        }

        .notif-indicator {
          font-weight: bold;
          color: var(--primary-color);
        }

        .unread-item .notif-indicator {
          color: #fb6165;
        }

        .item-desc {
          font-size: 0.8rem;
