1	import { useState, type FormEvent } from 'react';
2	import { useNavigate, Link } from 'react-router-dom';
3	import { useAuth } from '../context/AuthContext';
4	import ErrorMessage from '../components/ErrorMessage';
5	import client from '../api/client';
6	
7	/**
8	 * CC98 风格用户登录页面
9	 */
10	export default function LoginPage() {
11	  const navigate = useNavigate();
12	  const { login } = useAuth();
13	  const [username, setUsername] = useState('');
14	  const [password, setPassword] = useState('');
15	  const [error, setError] = useState('');
16	  const [isLoading, setIsLoading] = useState(false);
17	
18	  const handleSubmit = async (e: FormEvent) => {
19	    e.preventDefault();
20	    setError('');
21	    setIsLoading(true);
22	
23	    try {
24	      const response = await client.post('/auth/login', {
25	        username,
26	        password,
27	      });
28	
29	      const { accessToken, refreshToken } = response.data;
30	
31	      // Store tokens FIRST so the axios interceptor can use them
32	      localStorage.setItem('access_token', accessToken);
33	      if (refreshToken) {
34	        localStorage.setItem('refresh_token', refreshToken);
35	      }
36	
37	      // Now fetch user role
38	      let userRole = 'USER';
39	      try {
40	        const userResponse = await client.get(`/users/${username}`);
41	        userRole = userResponse.data.role || 'USER';
42	      } catch (err) {
43	        // If user info fetch fails, default to regular user
44	        console.error('Failed to fetch user role', err);
45	      }
46	
47	      login(username, accessToken, userRole);
48	      navigate(`/profile/${username}`);
49	    } catch (err: any) {
50	      const message = err.response?.data?.message || '登录失败，请检查用户名或密码。';
51	      setError(message);
52	    } finally {
53	      setIsLoading(false);
54	    }
55	  };
56	
57	  return (
58	    <div className="cc98-auth-page container">
59	      <div className="cc98-auth-card">
60	        <div className="cc98-auth-header">
61	          <i className="fa fa-sign-in"></i> User Login
62	        </div>
63	
64	        {error && (
65	          <div className="cc98-error-box" style={{ margin: '1.25rem 1.5rem 0 1.5rem' }}>
66	            <i className="fa fa-exclamation-circle"></i> {error}
67	          </div>
68	        )}
69	
70	        <form onSubmit={handleSubmit} className="cc98-auth-form">
71	          {/* Username */}
