import { useState, type FormEvent } from 'react';
import { useNavigate } from 'react-router-dom';
import { useMutation } from '@tanstack/react-query';
import { changePassword } from '../api/user';
import Breadcrumbs from '../components/Breadcrumbs';

export default function ChangePasswordPage() {
  const navigate = useNavigate();
  const [oldPassword, setOldPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [error, setError] = useState('');

  const changeMutation = useMutation({
    mutationFn: changePassword,
    onSuccess: () => {
      navigate('/dashboard');
    },
    onError: (err: any) => {
      setError(err.response?.data?.message || '密码修改失败，请重试');
      setSuccess('');
    },
  });

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    if (newPassword.length < 6) {
      setError('新密码长度不能少于 6 位');
      return;
    }
    if (newPassword !== confirmPassword) {
      setError('两次输入的新密码不一致');
      return;
    }

    changeMutation.mutate({ oldPassword, newPassword });
  };

  return (
    <div className="cc98-editor-page container" style={{ marginTop: '1.5rem', marginBottom: '3rem' }}>
      <Breadcrumbs
        items={[
          { label: '论坛首页', href: '/' },
          { label: '个人中心', href: '/dashboard' },
          { label: '修改密码' }
        ]}
      />

      <div className="cc98-editor-card">
        <div className="cc98-editor-title-bar">
          <i className="fa fa-lock"></i> 修改密码
        </div>

        {error && (
          <div className="cc98-error-box" style={{ margin: '1.25rem 1.5rem 0 1.5rem' }}>
            <i className="fa fa-exclamation-circle"></i> {error}
          </div>
        )}

        <form onSubmit={handleSubmit} style={{ padding: '1.5rem' }}>
          <div className="cc98-form-group">
            <label htmlFor="oldPassword">当前密码</label>
            <input
              id="oldPassword"
              type="password"
              value={oldPassword}
              onChange={(e) => setOldPassword(e.target.value)}
              disabled={changeMutation.isPending}
              placeholder="请输入当前密码"
              className="cc98-form-control"
              required
            />
          </div>

          <div className="cc98-form-group">
            <label htmlFor="newPassword">新密码</label>
            <input
              id="newPassword"
              type="password"
              value={newPassword}
              onChange={(e) => setNewPassword(e.target.value)}
              disabled={changeMutation.isPending}
              placeholder="请输入新密码（至少 6 位）"
              className="cc98-form-control"
              required
              minLength={6}
            />
          </div>

          <div className="cc98-form-group">
            <label htmlFor="confirmPassword">确认新密码</label>
            <input
              id="confirmPassword"
              type="password"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              disabled={changeMutation.isPending}
              placeholder="请再次输入新密码"
              className="cc98-form-control"
              required
              minLength={6}
            />
          </div>

          <div className="cc98-editor-actions">
            <button
              type="submit"
              className="cc98-btn btn-publish"
              disabled={changeMutation.isPending}
            >
              <i className="fa fa-check"></i> {changeMutation.isPending ? '修改中...' : '确认修改'}
            </button>
            <button
              type="button"
              onClick={() => navigate('/dashboard')}
              className="cc98-btn btn-cancel"
              disabled={changeMutation.isPending}
            >
              返回
            </button>
          </div>
        </form>
      </div>

      <style>{`
        .cc98-editor-card {
          background-color: var(--card-bg);
          border: 1px solid var(--border-color);
          border-radius: var(--cc98-radius);
          box-shadow: var(--cc98-shadow);
          overflow: hidden;
        }

        .cc98-editor-title-bar {
          background-color: var(--primary-color);
          color: white;
          padding: 0.85rem 1.5rem;
          font-weight: bold;
          font-size: 1.05rem;
          border-bottom: 2px solid var(--accent-color);
          display: flex;
          align-items: center;
          gap: 0.5rem;
        }

        .theme-dark .cc98-editor-title-bar {
          border-bottom-color: var(--border-color);
        }

        .cc98-error-box {
          background-color: rgba(251, 97, 101, 0.1);
          color: #fb6165;
          padding: 0.75rem 1.25rem;
          border-radius: var(--cc98-radius);
          border: 1px solid rgba(251, 97, 101, 0.2);
          font-size: 0.9rem;
          display: flex;
          align-items: center;
          gap: 0.5rem;
        }

        .cc98-form-group {
          margin-bottom: 1.5rem;
        }

        .cc98-form-group label {
          display: block;
          margin-bottom: 0.5rem;
          font-weight: bold;
          font-size: 0.92rem;
          color: var(--text-main);
        }

        .cc98-form-control {
          width: 100%;
          padding: 0.75rem;
          border: 1px solid var(--border-color);
          background-color: var(--card-bg);
          color: var(--text-main);
          border-radius: 4px;
          font-size: 0.95rem;
          font-family: inherit;
          transition: var(--cc98-transition);
        }

        .cc98-form-control:focus {
          border-color: var(--primary-color);
          outline: none;
          box-shadow: 0 0 0 3px rgba(84, 110, 122, 0.15);
        }

        .cc98-editor-actions {
          display: flex;
          gap: 1rem;
          margin-top: 2rem;
        }

        .cc98-btn {
          padding: 0.7rem 1.5rem;
          font-size: 0.92rem;
          font-weight: bold;
          border-radius: var(--cc98-radius-pill);
          cursor: pointer;
          transition: var(--cc98-transition);
          display: inline-flex;
          align-items: center;
          justify-content: center;
          gap: 0.4rem;
          border: none;
        }

        .btn-publish {
          background-color: var(--primary-color);
          color: white;
          flex: 1;
          min-width: 150px;
          box-shadow: 0 3px 6px rgba(0, 0, 0, 0.1);
        }

        .btn-publish:hover:not(:disabled) {
          background-color: var(--accent-color);
          color: #333;
          transform: translateY(-1px);
        }

        .btn-cancel {
          background-color: transparent;
          color: var(--text-muted);
          border: 1px solid var(--border-color);
          padding: 0.7rem 2rem;
        }

        .btn-cancel:hover:not(:disabled) {
          background-color: var(--quote-bg);
          color: var(--text-main);
        }

        .cc98-btn:disabled {
          opacity: 0.5;
          cursor: not-allowed;
        }
      `}</style>
    </div>
  );
}

