  const newPassword = await page.locator('label:has-text("新密码")').count();
  const confirmPassword = await page.locator('label:has-text("确认新密码")').count();
  console.log(`   Password form visible: ${passwordTitle > 0 ? 'YES' : 'NO'}`);
  console.log(`   Old password field: ${oldPassword > 0 ? 'YES' : 'NO'}`);
  console.log(`   New password field: ${newPassword > 0 ? 'YES' : 'NO'}`);
  console.log(`   Confirm password field: ${confirmPassword > 0 ? 'YES' : 'NO'}`);

  // Test validation: short password
  await page.fill('input#oldPassword', 'old123');
  await page.fill('input#newPassword', 'abc');
  await page.fill('input#confirmPassword', 'abc');
  await page.click('button:has-text("确认修改")');
  await page.waitForTimeout(500);
  await screenshot(page, '06-password-short');
  const shortError = await page.locator('text=新密码长度不能少于 6 位').count();
  console.log(`   Short password validation: ${shortError > 0 ? 'YES' : 'NO'}`);

  // Test validation: mismatch
  await page.fill('input#newPassword', 'newpassword123');
  await page.fill('input#confirmPassword', 'different123');
  await page.click('button:has-text("确认修改")');
  await page.waitForTimeout(500);
  await screenshot(page, '07-password-mismatch');
  const mismatchError = await page.locator('text=两次输入的新密码不一致').count();
  console.log(`   Password mismatch validation: ${mismatchError > 0 ? 'YES' : 'NO'}`);

  // ---- 6. Admin User Management ----
  console.log('\n6. Loading admin user management...');
  await page.goto('http://localhost:5173/admin/users', { waitUntil: 'networkidle' });
  await page.waitForTimeout(1500);
  await screenshot(page, '08-admin-users');

  const roleSelect = await page.locator('select').count();
  console.log(`   Role dropdown(s) present: ${roleSelect}`);

  if (roleSelect > 0) {
    // Check the select options
    const options = await page.locator('select:first-of-type').locator('option').count();
    console.log(`   Select options count: ${options}`);

    // Try clicking the select to see options
    await page.locator('select:first-of-type').click();
    await screenshot(page, '09-role-dropdown-open');
    console.log('   Role dropdown opened for screenshot');
  }

  // ---- 7. Admin Content Moderation ----
  console.log('\n7. Loading admin content moderation...');
  await page.goto('http://localhost:5173/admin/content', { waitUntil: 'networkidle' });
  await page.waitForTimeout(1500);
  await screenshot(page, '10-content-moderation');

  const postTab = await page.locator('text=帖子审核').count();
  console.log(`   Post tab visible: ${postTab > 0 ? 'YES' : 'NO'}`);

  // Click comments tab
  const commentTab = await page.locator('text=评论审核').count();
  if (commentTab > 0) {
    await page.click('text=评论审核');
    await page.waitForTimeout(1000);
    await screenshot(page, '11-content-comments-tab');
    console.log('   Comments tab clicked');
  }

  // ---- Done ----
  console.log('\n=== Smoke Test Complete ===');
  console.log(`Screenshots saved to: ${SCREENSHOT_DIR}`);

  await browser.close();
})();

